// Define all NodeIDs from configuration
const nodeIds = [
    'Ext1.BarrelZone[1].Temp.Set',
    'Ext1.BarrelZone[1].Temp.Act',
    'Ext1.BarrelZone[2].Temp.Set',
    'Ext1.BarrelZone[2].Temp.Act',
    'Ext1.BarrelZone[3].Temp.Set',
    'Ext1.BarrelZone[3].Temp.Act',
    'Ext1.BarrelZone[4].Temp.Set',
    'Ext1.BarrelZone[4].Temp.Act',
    'Ext1.BarrelZone[5].Temp.Set',
    'Ext1.BarrelZone[5].Temp.Act',
    'Die1.DieZone[1].Temp.Set',
    'Die1.DieZone[1].Temp.Act',
    'Die1.DieZone[2].Temp.Set',
    'Die1.DieZone[2].Temp.Act',
    'Die1.DieZone[3].Temp.Set',
    'Die1.DieZone[3].Temp.Act',
    'Die1.DieZone[4].Temp.Set',
    'Die1.DieZone[4].Temp.Act',
    'Ext1.Global.MeltPress[1].Act',
    'Ext1.Global.MeltTemp[1].Act',
    'Cal1.DcWater.Press.Set',
    'Cal1.DcWater.Press.Act',
    'Cal1.WcWater.Press.Set',
    'Cal1.WcWater.Press.Act',
    'Ext1.Feed[1].ScrewSpeed.Set',
    'Ext1.Feed[1].ScrewSpeed.Act',
    'Ext1.Feed[1].Throughput.Calc',
    'Ext1.Feed[2].ScrewSpeed.Set',
    'Ext1.Feed[2].ScrewSpeed.Act',
    'Ext1.Feed[2].Throughput.Calc',
    'Cal1.Recipe.Name'
];

const messages = [];
const identifierPrefix = 'ns=1;s=Memory.OpcUaLine.';

// Erste Message: clearitems um die liste im CLient zu leeren. Leert sich nicht von selbst! Man könnte die liste einmal füllen und dann einfach immer abfragen.
messages.push({
    topic: 'clearitems',
    payload: ''
});

// Alle NodeIDs hinzufügen
for (let index = 0; index < nodeIds.length; index++) {
    messages.push({
        topic: identifierPrefix + nodeIds[index],
        payload: 'Integer'
    });
}

// Letzte Message: readmultiple. Nur diese message ohne clear auch möglich
messages.push({
    topic: 'readmultiple',
    payload: 'ALL'
});

// Für Split Node
msg.payload = messages;
return [messages];

// Wenn ALL gelesen wurden ( alle oin einem payload) wird das paket verarbeitet
if (msg.topic === 'ALL' && Array.isArray(msg.payload) && Array.isArray(msg.items)) {
    const timestamp = new Date().toISOString();
    const processedData = {};

    msg.payload.forEach((valueItem, index) => {
        if (msg.items[index] && valueItem.value !== undefined) {
            const nodeId = String(msg.items[index].nodeId);

            const originalParamName = nodeId.replace('ns=1;s=Memory.OpcUaLine.', '');

            processedData[originalParamName] = valueItem.value.value;
        }
    });

    const mqttMessage = {
        device_id: "5023996",
        timestamp: timestamp,
        ...processedData
    };

    return [
        {
            topic: "polipol/8900/pla/pla-wyt/pla-wyt1/5023996/output_nr",
            payload: mqttMessage,
            qos: 1,
            retain: false
        },
        {
            topic: "debug_data",
            payload: {
                originalStructure: processedData,
                finalMessage: mqttMessage
            }
        }
    ];
}

return null;

